  ${hasIcon ? `icon="${computedIconName}"` : ""}
  ${hasIcon && iconPlace ? `icon-place="${iconPlace}"` : ""}
></dsfr-button>`;
export default {
    example: codeExample,
    id: figma.batch.id,
    metadata: {
        nestable: true,
    },
};

